from lecture_common import S,E,Q,L

def lessons():
 return [
 L(12,3,'네트워크의 이해: OSI와 주소','1. 네트워크의 이해 · 1~4계층',[
 S(4,'OSI 7계층의 전체 구조','ISO의 OSI 모델은 서로 다른 네트워크 시스템의 통신 기능을 일곱 계층으로 나누어 이해하는 참조 모델입니다. 송신 측은 상위 데이터에 각 계층의 제어 정보를 붙이고, 수신 측은 대응 계층에서 이를 해석합니다.',table=(['계층','PPT의 주요 역할'],[['7 응용','사용자·응용프로세스에 네트워크 서비스 제공'],['6 표현','데이터 표현·변환, 압축·암호화'],['5 세션','양 끝 응용프로세스의 대화 관리'],['4 전송','끝단 프로세스 사이 데이터 전달과 흐름 관리'],['3 네트워크','여러 노드·망을 거치는 경로와 논리 주소'],['2 데이터 링크','인접 구간의 프레임·MAC 주소·오류 관리'],['1 물리','신호·케이블·전기적/물리적 연결'] ])),
 S([5,6,7],'물리 계층: 케이블과 커넥터','물리 계층은 비트를 신호로 전달하는 연결 조건을 다룹니다. UTP는 비차폐 꼬임선, FTP는 포일 차폐, STP는 차폐 구조를 갖는 케이블의 예입니다. 차폐·케이블 등급·거리·장비 조건은 실제 연결 품질에 영향을 줍니다.','PPT는 케이블 카테고리(CAT), RJ11 전화용 커넥터와 RJ45 계열 LAN 커넥터를 비교합니다. 아래 수치는 PPT 왼쪽 표의 표기이며 오른쪽 연혁 그림과도 일부 다릅니다. 특히 CAT6의 250은 대역폭 MHz와 데이터 전송률 Mbps를 구분해 정정할 항목입니다.',table=(['CAT','PPT 왼쪽 표의 최대 속도 표기','제시된 용도'],[['1','1Mbps 미만','아날로그 전화·ISDN·초인종'],['2','4Mbps','IBM 토큰링'],['3','16Mbps','10BASE-T의 음성·데이터'],['4','20Mbps','16Mbps 토큰링'],['5','100Mbps','10/100BASE-T·토큰링·ATM'],['6','250Mbps로 표기','기가비트 이더넷 등 · 단위 혼동 주의'],['7','10Gbps','10기가비트 이더넷'] ])),
 S(8,'데이터 링크 계층과 MAC 주소','데이터 링크 계층은 인접한 구간의 프레임 전달, 오류 검출(CRC), 흐름 제어 같은 기능을 설명합니다. 이더넷 MAC은 48비트이며 16진수 열두 자리로 표현합니다.','PPT는 앞의 여섯 16진수 자리인 제조사 식별 부분과 뒤의 장치 식별 부분을 나눕니다. ipconfig /all 등의 출력에서 어댑터별 물리 주소를 확인할 수 있습니다. MAC은 네트워크 인터페이스를 식별하는 값이지 사용자의 확정 신원은 아닙니다.'),
 S([9,10,11],'스위치의 MAC 학습과 전달','스위치는 들어온 프레임의 출발지 MAC과 수신 포트를 학습하고, 목적지 MAC을 테이블에서 찾아 해당 포트로 전달합니다. 같은 망 안에서 어느 포트로 프레임을 보낼지 결정하는 과정입니다.','캡슐화 그림에서는 데이터가 프레임 안에 실리고 프레임에 출발지·목적지 MAC이 포함됩니다. 스위치의 기본 전달 테이블은 IP 주소표가 아니라 MAC 주소와 포트의 대응입니다. 목적지를 아직 모르는 경우의 전달과 정상적으로 학습한 뒤의 전달을 구분합니다.'),
 S([12,13],'네트워크 계층: IPv4와 클래스','IPv4 주소는 8비트 네 개, 총 32비트입니다. PPT의 11000000.10101000.00000000.01100100은 각각 192·168·0·100이므로 192.168.0.100입니다. 라우터는 논리 주소와 경로를 이용해 서로 다른 망 사이로 패킷을 전달합니다.','PPT의 A·B·C 클래스는 과거의 고정 네트워크/호스트 경계입니다. 아래 표의 호스트 비트 수는 주소 공간 크기이며 모든 값을 일반 호스트에 할당할 수 있다는 뜻은 아닙니다. 현대의 실제 망 구분은 프리픽스 길이도 함께 확인합니다.',table=(['클래스','시작 비트·첫 옥텟','PPT의 구분'],[['A','0 · 0~127','네트워크 8비트 / 호스트 24비트'],['B','10 · 128~191','네트워크 16비트 / 호스트 16비트'],['C','110 · 192~223','네트워크 24비트 / 호스트 8비트'],['D','1110 · 224~239','멀티캐스트 주소 범위'],['E','1111 · 240~255','예약·특수 목적 범위'] ])),
 S([14,15,16,17],'라우터·게이트웨이와 다음 홉','다른 네트워크의 호스트로 보낼 때 송신자는 목적지 IP를 유지하면서 로컬 구간의 프레임을 게이트웨이 MAC으로 보냅니다. ARP는 같은 링크에서 필요한 IP와 MAC 대응을 확인하는 과정입니다.','각 라우터는 목적지 IP를 보고 다음 경로를 결정하고, 다음 링크에 맞는 출발지·목적지 MAC으로 새 프레임을 만듭니다. 따라서 홉마다 프레임의 주소가 달라집니다. NAT 같은 변환이 없다면 양 끝단 IP는 유지되며, 멀리 있는 목적지 호스트의 MAC을 모든 구간에 그대로 넣지 않습니다.'),
 S([18,19,20],'전송 계층: 포트와 연결 상태','전송 계층의 포트는 같은 호스트 안에서 응용프로세스를 구분하는 데 쓰입니다. IP만으로 어느 프로그램의 요청인지 모두 결정되지 않으므로 출발지·목적지 IP와 포트를 함께 읽습니다. TCP의 순서번호는 전송 바이트의 순서와 확인에 관련됩니다.','PPT는 잘 알려진 서비스 포트와 임시 포트 1025~65535를 비교합니다. 실제 임시 포트 범위는 운영체제·설정에 따라 달라집니다. netstat -an의 LISTEN은 접속을 기다리는 상태, ESTABLISHED는 연결이 성립한 상태의 예입니다. 목록만으로 서비스의 취약성이나 실제 사용자를 확정하지 않습니다.')
 ],[Q('스위치와 라우터의 대표적인 전달 기준은?','스위치는 MAC과 포트, 라우터는 IP와 경로를 기준으로 전달한다.','인접 링크와 서로 다른 망의 전달을 구분합니다.'),Q('다른 망으로 보낼 때 로컬 프레임의 목적지 MAC은?','해당 링크의 게이트웨이 또는 다음 홉 MAC이다.','최종 목적지 IP와 바로 다음 수신 장치의 MAC은 역할이 다릅니다.'),Q('LISTEN과 ESTABLISHED의 차이는?','연결 대기 상태와 성립한 연결 상태다.','포트·주소·프로토콜과 함께 해석합니다.')],[E('PPT의 케이블·주소 표를 읽는 기준','PPT의 CAT 표와 오른쪽 연혁 그림은 같은 등급에 서로 다른 전송률을 제시합니다. CAT6의 250MHz 같은 주파수 대역폭과 실제 링크 전송률을 혼합해서 외우지 않습니다. 전송률은 적용 이더넷 규격·길이·장비에 따라 판단합니다.','클래스 A의 0·127 대역 등에는 특수 용도가 있으므로 표의 전체 비트 조합 수를 사용 가능한 일반 호스트 수로 그대로 쓰지 않습니다. 클래스 표는 역사적 분류이며 실제 네트워크/호스트 경계는 서브넷 마스크·CIDR 프리픽스로 확인합니다.')]),
 L(13,3,'TCP·UDP와 상위 계층','1. 네트워크의 이해 · 연결과 상위 계층',[
 S(21,'TCP의 3-way handshake','클라이언트는 SYN을 보내며 SYN-SENT, 서버는 SYN을 받고 SYN+ACK로 응답하며 SYN-RECEIVED 상태가 됩니다. 클라이언트가 ACK를 보내고 서버가 이를 받으면 양쪽이 ESTABLISHED 상태로 통신합니다.','세 메시지는 양방향의 초기 순서와 수신 가능 상태를 확인하는 과정입니다. SYN만 관찰한 상태와 연결이 완료된 상태를 구분해야 이후 SYN flooding이나 연결 기록을 해석할 수 있습니다.'),
 S(22,'TCP 연결 종료와 상태 변화','PPT의 먼저 닫는 쪽은 FIN을 보내 FIN-WAIT-1이 되고, 상대는 이를 받아 CLOSE-WAIT가 된 뒤 ACK를 보냅니다. 먼저 닫는 쪽은 ACK를 받으면 FIN-WAIT-2가 됩니다.','상대 응용프로그램도 닫으면 FIN을 보내 LAST-ACK가 되고, 먼저 닫은 쪽은 마지막 ACK 후 TIME-WAIT를 거칩니다. 상대는 ACK를 받으면 CLOSED로 끝납니다. TIME-WAIT의 대기는 이전 연결의 지연된 데이터와 마지막 응답 처리를 위한 과정이며 PPT는 2MSL로 표시합니다.'),
 S(23,'TCP와 UDP 비교','TCP는 연결 상태, 순서, 확인 응답과 재전송·흐름 제어를 통해 신뢰성 있는 바이트 스트림을 제공합니다. UDP는 TCP와 같은 연결 설정 없이 데이터그램을 보내며 그 자체가 도착·순서·재전송을 보장하지 않습니다.','UDP를 사용하는 응용프로그램이 별도의 신뢰성 기능을 가질 수 있으므로 UDP라는 이유만으로 모든 상위 서비스가 복구 기능이 없다고 단정하지 않습니다. 요구하는 지연·처리 방식·전달 보장을 기준으로 비교합니다.'),
 S(24,'세션·표현·응용 계층','세션 계층은 대화의 시작·유지·종료, 반이중·전이중 통신, 체크포인트와 재개 같은 기능으로 설명됩니다. TCP 상태와 OSI의 세션 기능을 무조건 같은 것으로 외우지 않습니다.','표현 계층은 데이터 형식 변환, ASN.1 같은 표현, 압축·암호화 등을 설명합니다. 응용 계층은 HTTP·FTP·전자우편·원격 터미널·디렉터리 등 응용 서비스와 연결됩니다. 실제 인터넷 구현은 OSI의 일곱 상자가 항상 독립 프로그램으로 나뉘는 것은 아닙니다.'),
 S(25,'계층·주소·공격 지점 연결','MAC은 로컬 링크 전달, IP는 호스트·망의 경로, 포트는 응용프로세스 구분이라는 역할에 대응시킵니다. 공격을 볼 때 어느 값과 어느 상태를 속이거나 소모하는지 표시합니다.','다음 홉을 바꾸는 공격과 최종 목적지 이름을 바꾸는 공격, TCP 연결 상태를 노리는 공격은 영향을 주는 지점이 다릅니다. 계층과 정상 동작을 먼저 알면 뒤의 스니핑·스푸핑·하이재킹을 비교할 수 있습니다.')
 ],[Q('TCP 연결 설정의 메시지 순서는?','SYN, SYN+ACK, ACK다.','각 방향의 순서와 상태 성립을 확인합니다.'),Q('먼저 연결을 닫는 쪽의 대표 상태 흐름은?','FIN-WAIT-1 → FIN-WAIT-2 → TIME-WAIT → CLOSED다.','상대편의 CLOSE-WAIT·LAST-ACK와 구분합니다.'),Q('UDP는 응용 수준 재전송도 금지하나?','아니다. UDP 자체가 보장하지 않는 것이며 응용이 별도 구현할 수 있다.','프로토콜 자체의 기능과 서비스 전체 동작을 구분합니다.')]),
 L(14,3,'서비스 거부 공격: 비정상 패킷과 연결 고갈','2. 서비스 거부 공격: DoS와 DDoS · 기본 유형',[
 S([26,27],'DoS의 목적과 두 분류','서비스 거부(DoS)는 정상 사용자가 서비스를 사용하지 못하게 해 가용성을 침해하는 공격입니다. PPT의 노점상 비유는 처리할 수 있는 공간·시간을 공격 요청이 점유하는 상황을 설명합니다.','취약점 공격형은 비정상 입력을 처리하는 구현의 결함으로 오작동을 유발하고, 자원 고갈형은 대역폭·CPU·세션 등의 한계를 소모시킵니다. PPT는 Land 등을 양쪽 맥락에 중복 제시하므로 분류 이름보다 장애 원인을 설명해야 합니다.','PPT의 목록은 보잉크·봉크·티어드롭, Land, Ping of Death, SYN flooding, HTTP GET·CC·동적 요청 flooding, Slowloris, Slow HTTP POST, Smurf, 메일 폭탄으로 이어집니다.'),
 S([28,29],'보잉크·봉크·티어드롭: IP 단편 재조립','Boink·Bonk·Teardrop은 역사적인 IP 단편 처리 취약점 사례입니다. 수신자는 단편의 위치와 길이로 원래 IP 데이터그램을 재조립하는데, 겹치거나 비정상적인 단편을 취약한 구현이 처리하면 오류·중단·자원 소모가 생길 수 있습니다.','PPT의 정상 범위 [0..999], [1000..1999]는 이어지고, [0..999], [800..1799]는 800~999의 200바이트가 겹칩니다. 관련 계층은 IP가 있는 네트워크 계층이며 TCP 플래그 공격으로 바꾸어 설명하지 않습니다. 패치와 비정상 단편 검사가 관련 대응입니다.'),
 S(30,'Land 공격','PPT의 Land는 출발지와 목적지가 자기 자신을 가리키는 비정상 패킷의 예입니다. 취약한 구현에서 자기 자신에 대한 응답·처리 반복이나 장애가 발생할 수 있는 역사적 공격으로 이해합니다.','비정상 주소 조건과 구현의 결함이 핵심입니다. 운영체제 패치와 비정상 패킷 차단을 대응으로 연결하고, 모든 최신 장치에서 같은 결과가 난다고 가정하지 않습니다.'),
 S(31,'Ping of Death와 크기·재조립 문제','죽음의 핑(Ping of Death)은 허용 범위를 벗어나는 크기의 패킷을 단편 재조립 등으로 처리할 때 취약한 구현이 장애를 일으키는 역사적 공격입니다. PPT에서 크기·단편과 장애의 관계를 읽습니다.','큰 패킷 처리 결함과 단순히 많은 ICMP 요청을 보내 대역폭을 소모하는 flooding은 원인이 다릅니다. 패치와 비정상 크기 검사, 필요한 네트워크 진단 기능을 고려해 대응을 구분합니다.'),
 S(32,'SYN flooding','많은 SYN에 대해 서버가 SYN+ACK와 미완료 연결 상태를 만들지만 마지막 ACK가 오지 않으면 대기 상태와 처리 자원이 소모될 수 있습니다. PPT의 핵심은 연결이 완료되기 전 자원이 점유된다는 점입니다.','SYN cookie·SYN proxy·연결 제한 등은 상태 소모를 줄이는 대응입니다. 이미 회선 대역폭이 소진되는 경우에는 상위 네트워크의 대응도 필요합니다. SYN 수만이 아니라 완료 ACK·연결 상태·실제 부하를 함께 확인합니다.')
 ],[Q('보잉크·봉크·티어드롭의 공통 취약 지점은?','비정상 IP 단편을 재조립하는 구현이다.','TCP 플래그가 아니라 네트워크 계층의 처리 문제입니다.'),Q('Ping of Death와 일반 ping flooding은 무엇이 다른가?','비정상 크기 처리 결함과 대량 요청에 의한 자원 소모라는 원인이 다르다.','두 유형을 단순히 ping 명령의 유무로 구분하지 않습니다.'),Q('SYN flooding에서 완료되지 않는 단계는?','SYN+ACK 뒤에 필요한 마지막 ACK가 오지 않아 연결 설정이 끝나지 않는다.','미완료 상태와 서버 자원을 연결합니다.')]),
 L(15,3,'서비스 거부 공격: HTTP·반사·분산','2. 서비스 거부 공격: DoS와 DDoS · 응용과 분산',[
 S(33,'HTTP GET flooding','TCP 연결과 정상 형태의 HTTP 요청을 이용해 웹 서버의 요청 처리량·CPU·DB 조회 등의 자원을 소모합니다. 정상 문법의 요청이어도 비정상적으로 많거나 비용이 큰 작업에 집중되면 장애가 생길 수 있습니다.','패킷 한 개의 오류만 찾는 방식으로는 설명이 부족합니다. 요청률, 대상 경로, 처리 비용과 사용자별 제한을 함께 봅니다.'),
 S(34,'HTTP CC·동적 요청·느린 요청','PPT의 HTTP CC는 Cache-Control: no-store, must-revalidate 같은 캐시 관련 값으로 서버의 직접 처리를 유도하는 유형입니다. 동적 HTTP 요청은 URL·매개변수를 바꾸어 캐시로 반복 요청을 처리하기 어렵게 합니다. 헤더를 넣었다는 사실만으로 모든 서버가 같은 비용을 쓰는 것은 아닙니다.','Slowloris는 요청 헤더를 천천히 끝내고, Slow HTTP POST는 본문을 천천히 보내 연결·작업 자원을 붙잡습니다. 짧은 시간의 대역폭뿐 아니라 오래 점유하는 연결, 요청 제한시간과 최소 전송 속도 같은 조건을 봅니다.'),
 S([35,36,37],'Smurf의 반사·증폭 과정','공격자는 출발지 IP를 피해자로 위조한 ICMP Echo 요청을 브로드캐스트 가능한 망으로 보냅니다. 여러 호스트가 응답하면 응답이 피해자에게 모여 반사·증폭 피해를 줄 수 있습니다. 공격 요청을 받은 장치와 최종 응답 피해자를 구분합니다.','PPT는 브로드캐스트 주소와 라우터를 거치는 직접 브로드캐스트를 설명합니다. 255.255.255.255는 제한 브로드캐스트이고, 172.16.0.255 같은 직접 브로드캐스트 판정에는 /24 등 실제 마스크 조건이 필요합니다. 라우터의 직접 브로드캐스트 전달 제한과 출발지 검증을 대응으로 연결합니다.'),
 S([38,39],'메일 폭탄과 DDoS의 역할','메일 폭탄은 대량 메일로 저장 공간·메일 처리·이용자의 정상 사용을 방해하는 예입니다. 할당량·수신 정책과 처리 자원 통제가 관련됩니다.','DDoS는 여러 장치가 분산해 공격하는 방식입니다. PPT의 공격자, 마스터/핸들러, 에이전트/데몬 역할을 구분합니다. 명령을 전달하는 중간 장치와 실제 공격 트래픽을 보내는 장치는 침해된 피해 장치일 수도 있습니다.','분산과 위조로 추적·대응이 어려워지지만 「방어가 전혀 불가능하다」는 절대 명제로 외우지 않습니다. 장치 감염 방지와 네트워크·서비스 단계별 대응이 필요합니다.'),
 S([40,41],'봇넷의 형성과 공격 흐름','악성코드 유포·감염 뒤 장치가 잠복 봇 또는 좀비가 되고, 여러 장치가 명령·예약에 따라 행동하는 봇넷으로 연결됩니다. 이후 특정 목표로 동시에 트래픽을 보내는 단계로 이어집니다.','PPT의 단계 그림은 악성코드의 확산, 제어 관계, 실제 공격 시작을 구분합니다. 감염됐다는 상태와 현재 특정 DDoS를 수행했다는 관찰은 다르므로 시점과 통신 근거를 확인합니다.'),
 S(42,'고갈되는 자원에 맞춘 대응','대역폭 공격은 상위 망의 필터링·우회·정화, TCP 상태 고갈은 SYN cookie·proxy·상태 관리, HTTP/API 처리 고갈은 요청 제한·캐시·WAF·비용 큰 작업 제어와 연결합니다.','하나의 방어 장치가 모든 유형을 같은 방식으로 처리하지 않습니다. 병목이 회선인지, 연결 상태인지, 애플리케이션·DB인지 먼저 확인하고 대응 위치를 정합니다.')
 ],[Q('Slowloris와 느린 POST는 무엇을 천천히 보내나?','요청 헤더와 요청 본문을 각각 천천히 보낸다.','연결·작업의 장시간 점유가 핵심입니다.'),Q('Smurf에서 위조하는 출발지와 응답 목적지는?','출발지를 피해자 IP로 위조해 반사 응답이 피해자에게 향하게 한다.','공격자·반사 장치·피해자를 분리해서 그립니다.'),Q('DDoS 대응 전에 먼저 찾아야 할 병목은?','회선 대역폭·연결 상태·응용 처리 등 고갈되는 자원이다.','방어를 놓을 위치와 방식이 달라집니다.')]),
 L(16,3,'스니핑 공격','3. 스니핑 공격',[
 S(43,'스니핑의 개념','스니핑은 통신 내용을 엿듣는 행위로, 전달 내용을 직접 바꾸지 않는 수동적 관찰의 성격을 설명합니다. PPT는 도청과 TEMPEST 같은 정보 누출 관찰의 맥락도 소개합니다.','어디서 어떤 신호·프레임을 볼 수 있는지가 먼저 정해져야 합니다. 관찰 위치와 실제로 해독 가능한 내용은 구분합니다.'),
 S([44,45],'NIC 필터와 promiscuous 모드','일반 NIC는 자신에게 해당하는 프레임과 필요한 브로드캐스트 등을 처리합니다. promiscuous 모드는 수신된 프레임을 더 넓게 관찰하도록 필터 동작을 바꾸는 예입니다.','이 모드를 켰다고 스위치가 다른 포트에만 보낸 프레임이 자동으로 내 포트에 생기지는 않습니다. PPT의 필터 그림을 읽을 때 「프레임이 해당 인터페이스에 전달되는 조건」과 「받은 프레임을 처리하는 조건」을 나눕니다.'),
 S(46,'스위치 재밍(MACOF)과 SPAN·태핑','MACOF 또는 MAC flooding은 많은 임의의 출발지 MAC을 보내 스위치 MAC 테이블의 용량·학습 동작을 압박하는 방식입니다. 목적지를 모르는 프레임 전달이 늘어나 관찰 범위가 바뀔 수 있지만 장비의 구현·보호 기능에 따라 결과가 다릅니다.','SPAN 포트는 스위치의 포트 미러링으로 특정 트래픽의 복사본을 전달하는 관찰 지점입니다. 하드웨어 탭은 물리적인 장치로 통신을 복제합니다. IDS·모니터링·로그 수집에 쓰는 정당한 관찰과 무단 관찰은 설정 권한과 목적·승인 기록으로 구분합니다.'),
 S([47,48],'ping·ARP·DNS 반응을 이용한 탐지','대리 출석 비유는 직접 확인한 사실과 다른 단서를 통한 추정을 구분하게 합니다. PPT의 ping·ARP 탐지는 평소 응답하지 않을 MAC/주소 조건을 만들어 예상 밖의 반응을 관찰하는 아이디어입니다.','DNS 탐지는 수집 도구가 관찰한 주소의 이름을 찾느라 역방향 조회를 하는 행동을 단서로 삼습니다. 이러한 반응은 도구 설정과 환경에 따라 없거나 다른 원인으로 생길 수 있으므로 확정 판정이 아닌 탐지 신호입니다.'),
 S(49,'유인 정보와 ARPwatch','가짜 계정정보 같은 유인 자료를 준비해 누군가 이를 사용하는지 관찰하는 방법과, ARPwatch로 IP–MAC 대응 변화를 감시하는 방법이 PPT에 등장합니다.','관찰한 사용 시각·주체·ARP 변화가 실제 스니핑과 연결되는지 다른 로그·설정과 대조합니다. 정상 네트워크 변경도 ARP 변화를 만들 수 있어 한 신호로 침해를 확정하지 않습니다.')
 ],[Q('promiscuous 모드만으로 스위치의 모든 통신을 볼 수 있나?','아니다. 그 인터페이스에 프레임이 전달돼야 한다.','수신 경로와 NIC 필터는 다른 조건입니다.'),Q('MACOF와 SPAN의 차이는?','MAC 학습 테이블을 압박하는 방식과 미러링 설정으로 복사하는 방식이다.','동작 원리·권한·승인을 구분합니다.'),Q('DNS 역조회·ARP 변화가 스니핑의 확정 증거인가?','아니다. 환경과 다른 원인을 대조할 탐지 신호다.','유인 정보 사용과 설정·로그를 함께 확인합니다.')]),
 L(17,3,'스푸핑 공격','4. 스푸핑 공격',[
 S([50,51,52],'ARP 스푸핑의 정상·위조 흐름','정상 ARP는 같은 링크에서 IP에 대응하는 MAC을 확인합니다. PPT 예에서 서버 10.0.0.2의 MAC을 AA, 클라이언트 10.0.0.3의 MAC을 BB, 공격자 MAC을 CC로 나타냅니다.','공격자가 양쪽의 IP–MAC 대응을 자신인 CC로 속이면 서로에게 보낼 프레임이 공격자에게 향할 수 있습니다. 공격자가 전달을 계속하면 중간자 경로가 되고, 전달하지 않으면 통신 장애가 생길 수 있습니다. arp -a로 현재 캐시를 확인하고 arp -s 같은 정적 대응은 제한된 환경의 대응 예입니다.'),
 S([53,54,55],'IP 스푸핑과 과거의 r 신뢰 관계','IP 스푸핑은 패킷의 출발지 IP를 다른 호스트처럼 보이게 하는 방식입니다. PPT는 과거의 호스트 기반 신뢰에서 정상 클라이언트를 방해하고 그 주소로 위장해 서버의 신뢰를 악용하는 상황을 설명합니다.','PPT의 host.equiv는 hosts.equiv라는 파일명과 구분해야 합니다. 이 파일과 r 계열 서비스는 호스트/사용자 신뢰에 관한 역사적 설정이며, IP를 신원으로 과신하는 문제가 핵심입니다. PPT의 「제로 트러스트 클라이언트」라는 표현은 현대 제로 트러스트 개념과 맞지 않아 별도 정정했습니다.'),
 S([56,57],'ICMP Redirect: 정상 경로 안내와 위조','정상적인 예는 호스트가 라우터 A로 보냈지만 같은 링크의 라우터 B가 더 적절한 다음 홉일 때 경로 변경을 알려 주는 상황입니다. 목적지와 새 게이트웨이의 관계를 경로표에 반영합니다.','위조된 Redirect를 받아들이면 공격자가 원하는 경로로 패킷이 향할 수 있습니다. PPT의 경로 그림에서는 보낸 주체, 원래 게이트웨이, 안내된 다음 홉을 구분합니다. 모든 임의의 원격 메시지를 모든 호스트가 받아들이는 것은 아니며 수용 조건은 별도 해설에서 보충합니다.'),
 S([58,59,60,61],'DNS 스푸핑: 이름과 응답의 위조','사용자가 도메인을 조회하면 클라이언트는 DNS 질의를 보내고 응답에서 IP 주소를 얻습니다. 공격자는 위조된 응답으로 도메인이 다른 서버를 가리키게 만들어 가짜 사이트 접속을 유도합니다.','PPT는 같은 네트워크에서 질의를 관찰하고 정상 응답보다 빨리 위조 응답을 보내는 흐름을 단계별로 보여 줍니다. 질의 관찰 가능성, 응답의 유효성, 클라이언트가 이를 채택하는 조건을 함께 봅니다. 속도가 빠르다는 사실만으로 아무 응답이나 유효한 것은 아닙니다.'),
 S([62,63],'캐시 오염과 hosts 파일의 범위','PPT는 잘못된 이름–IP 대응이 캐시에 남는 위험과 hosts 파일에 정적 대응을 두는 예를 설명합니다. hosts 파일은 전체 URL 경로가 아니라 호스트 이름과 IP를 연결합니다.','브로드캐스트 또는 요청하지 않은 응답을 보내면 반드시 모든 캐시가 오염된다는 표현은 정확하지 않습니다. 응답 검증과 캐시 정책에 따라 달라집니다. 정적 hosts도 관리 범위가 제한되고 모든 도메인·기기의 보호를 대신하지 못합니다.')
 ],[Q('ARP 스푸핑은 어떤 대응을 속이나?','같은 링크의 IP–MAC 대응을 속인다.','최종 목적지 이름을 바꾸는 DNS 공격과 구분합니다.'),Q('IP 스푸핑이 과거 호스트 신뢰에서 문제가 된 이유는?','출발지 IP를 신원의 충분한 근거로 취급했기 때문이다.','허용 호스트 표와 현대의 신원 검증을 구분합니다.'),Q('hosts 파일에 저장하는 대상은 전체 URL인가?','아니다. 호스트 이름과 IP 주소의 대응이다.','경로·프로토콜·포트까지 같은 값으로 취급하지 않습니다.')],[E('파일명·제로 트러스트·응답 조건 정정','정확한 파일명은 /etc/hosts.equiv입니다. 과거 호스트 신뢰의 실제 허용 여부는 사용자·서비스·PAM 등 조건도 영향을 줍니다. 이 방식을 현대의 제로 트러스트로 부르면 안 됩니다.','DNS 응답은 질의 ID·포트·이름/유형 등 대응 조건을 확인해야 하므로 먼저 도착했다는 이유만으로 모두 채택되는 것은 아닙니다. ICMP Redirect도 기존 게이트웨이와 같은 링크의 새 게이트웨이 등 검증 조건을 갖습니다.','ARP 경로를 가로챘다고 정상 검증되는 HTTPS의 암호문을 바로 복호화할 수 있는 것은 아닙니다. 경로 통제와 암호·인증 검증은 다른 경계입니다.',links=[('hosts.equiv 형식','https://man7.org/linux/man-pages/man5/hosts.equiv.5.html'),('RFC 5452 DNS 응답 검증','https://www.rfc-editor.org/rfc/rfc5452.html'),('RFC 1122 Redirect 검증','https://www.rfc-editor.org/rfc/rfc1122.html')])]),
 L(18,3,'세션 하이재킹 공격','5. 세션 하이재킹 공격',[
 S(64,'정상 연결을 가로채는 개념','PPT는 케빈 미트닉과 시모무라의 1995년 사건, 로그인된 자리를 타인이 이용하는 비유를 통해 새로 인증하는 대신 이미 성립한 연결을 악용하는 개념을 설명합니다.','정상 연결의 상태를 알고 그 상태에 맞는 메시지를 주입할 수 있는지, 피해자의 통신을 방해하거나 관찰할 수 있는지 같은 조건이 필요합니다. 역사적 공격의 전제와 현재 환경을 구분합니다.'),
 S(65,'TCP 상태와 RST의 의미','TCP 세션의 판단에는 양쪽 IP·포트와 순서번호·확인 응답 등의 상태가 관련됩니다. 단순히 같은 IP를 적었다는 것만으로 기존 연결의 유효한 데이터가 되지 않습니다.','RST는 연결을 중단시키는 신호입니다. 정상 연결에 유효한 RST를 주입해 끊었다는 사실이 공격자에게 인증 권한이 넘어갔다는 뜻은 아닙니다. 새 연결을 시작하면 별도의 연결 설정이 필요합니다.'),
 S(66,'웹 세션 토큰과 TCP 연결의 구분','웹 세션 하이재킹은 쿠키·세션 토큰을 탈취하거나 재사용해 서버가 같은 사용자로 받아들이는 문제입니다. 한 웹 세션이 여러 TCP 연결에서 사용될 수 있으므로 TCP 종료와 웹 로그아웃은 일치하지 않을 수 있습니다.','Secure·HttpOnly·SameSite, 로그인/권한 변경 시 회전, 만료, 로그아웃 후 서버 무효화를 목적에 맞게 적용합니다. PPT의 비교는 전송 계층의 연결 상태와 응용 계층의 인증 상태를 나누어 이해하도록 합니다.')
 ],[Q('TCP 하이재킹과 웹 세션 하이재킹의 상태는 무엇이 다른가?','연결의 주소·포트·순서 상태와 서버가 인정하는 인증 토큰 상태가 다르다.','동일한 세션이라는 단어가 계층별로 다른 대상을 가리킵니다.'),Q('RST로 연결을 끊으면 상대 권한을 자동으로 얻는가?','아니다. 연결 중단과 권한 획득은 다르다.','새 연결과 애플리케이션 인증이 별도로 필요합니다.'),Q('TCP 연결 종료가 웹 로그아웃을 보장하나?','아니다. 서버의 세션 토큰을 무효화하는 처리가 필요하다.','전송 연결과 인증 상태의 수명을 구분합니다.')]),
 L(19,3,'무선 네트워크 공격과 보안','6. 무선 네트워크 공격과 보안',[
 S([67,68],'AP와 전파 범위·안테나','무선 AP는 유선망과 무선 단말을 연결합니다. 전파는 건물·안테나·출력·장애물에 따라 원래 의도한 공간 밖까지 닿을 수 있습니다. PPT의 수십 미터~1·2km 범위는 환경 조건이 있는 예시입니다.','무지향성 안테나는 주변 방향으로, 지향성 안테나는 특정 방향으로 신호를 집중하는 구조로 비교합니다. 네트워크의 물리적 경계와 전파가 닿는 경계가 반드시 같지 않다는 점이 핵심입니다.'),
 S(69,'PPT의 주요 802.11 프로토콜 표','PPT는 주파수·최대 속도·호환성과 활용 환경을 비교합니다. 표의 연도는 PPT 연혁의 표기이며 초안·표준 승인·제품 출시 시점을 하나로 확정한 최신 표준표로 사용하지 않습니다. 최대 수치는 실제 사용자 처리량과 구분합니다.',table=(['PPT 표의 규격','주요 특징'],[['802.11 (1997)','2.4GHz / 2Mbps'],['802.11b (1999)','2.4GHz / 11Mbps, 초기 Wi-Fi·WEP'],['802.11a (1999)','5GHz / 54Mbps, b와 직접 호환되지 않음'],['802.11g (2003)','2.4GHz / 54Mbps, b 호환 환경 영향'],['802.11i (2004)','보안 개선 규격. 독립적인 무선 속도 세대와 구분'],['802.11n (PPT 2007)','2.4/5GHz·MIMO, 최대 600Mbps 설명'],['802.11ac (PPT 2012)','5GHz·넓은 채널(80~160MHz), 2.4GHz는 n 등과 구분'],['802.11ad (PPT 2014)','60GHz·최대 약 7Gbps, 장애물·짧은 거리 특성'],['802.11ah (PPT 2017)','1GHz 미만, 저전력·넓은 범위의 IoT 환경'],['802.11ay (PPT 2017)','60GHz, ad 개선·고속 전송 설명'] ])),
 S(70,'AP의 기본 보안 설정','AP의 설치 위치·출력·관리 계정과 비밀번호·펌웨어를 관리합니다. 접속 가능한 전파 범위를 고려하고, 무선 사용자와 관리 인터페이스 접근 권한을 구분합니다.','SSID 숨김은 네트워크 이름 노출을 줄이는 설정일 뿐 강한 인증·암호화를 대신하지 않습니다. WPA3 또는 호환성에 맞는 WPA2-AES(CCMP), 충분한 비밀정보와 업데이트가 중요한 보호 수단입니다.'),
 S([71,72,73],'WEP의 구조·공유키 인증·취약점','WEP는 RC4를 사용하는 과거 무선 보안 방식입니다. 64비트 표기는 비밀키 40비트와 IV 24비트, 128비트 표기는 비밀키 104비트와 IV 24비트의 합으로 설명됩니다. 표기 전체가 비밀키 길이는 아닙니다.','PPT의 공유키 인증 흐름은 연결 요청, AP의 평문 도전값, 클라이언트가 공유키로 암호화한 응답, AP의 복호화·비교입니다. SSID를 아는 것과 비밀키를 증명하는 과정은 다릅니다.','24비트 IV가 반복되고 많은 통신이 수집되면 키 복구 공격에 악용될 수 있습니다. PPT의 짧은 시간 내 해독 시연은 수집량·환경·구현 조건의 예이며 모든 상황에서 같은 시간에 성공한다는 보장은 아닙니다.'),
 S(74,'WPA·WPA2와 인증 방식의 두 축','WPA의 TKIP는 과거 RC4 기반 개선 방식이며, WPA2에서 사용하는 CCMP는 AES 기반 보호와 연결됩니다. WEP·TKIP·CCMP의 이름과 암호 기술을 대응시킵니다.','Personal의 PSK는 공유 비밀정보를 이용하고, Enterprise는 사용자별 인증 체계를 사용합니다. 암호화 방식과 사용자 인증 방식을 서로 다른 축으로 비교해야 합니다. WPA2라는 이름만 보고 모든 구성이 같은 강도라고 단정하지 않습니다.'),
 S([75,76],'802.1X와 RADIUS 인증 흐름','Supplicant는 접속하려는 단말, Authenticator는 AP 등 접속을 통제하는 장치, Authentication Server는 RADIUS 같은 인증 서버입니다. 인증 전에는 일반 네트워크 접근을 제한하고 인증 메시지를 전달합니다.','PPT의 도전·응답, 서버 확인, 키 설정과 암호화 통신의 순서에서 AP가 모든 사용자 비밀을 직접 검증하는 주체인지 구분합니다. 해시 기반 도전·응답 그림은 특정 인증 방식의 예이며 모든 EAP 방식이 동일하게 동작하는 것은 아닙니다.'),
 S(77,'무선 보안 선택의 종합','WEP·WPA-TKIP는 사용하지 않고, 기기 호환성에 맞춰 WPA3와 SAE·보호된 관리 프레임(PMF), 필요한 경우 WPA2-CCMP를 검토합니다. 조직에서는 802.1X와 사용자·인증서 관리까지 연결합니다.','관리자 계정·업데이트·강한 비밀정보·불필요한 기능 제한은 공통 관리 항목입니다. SSID 숨김이나 MAC 목록만으로 강한 인증·암호화를 대체하지 않는 이유를 설명할 수 있어야 합니다.')
 ],[Q('WEP의 64비트 표기는 무엇의 합인가?','40비트 비밀키와 24비트 IV의 합이다.','IV를 비밀키 길이와 혼동하지 않습니다.'),Q('802.1X의 세 주체는?','단말 Supplicant, AP 등의 Authenticator, RADIUS 등의 인증 서버다.','접속 제어와 실제 자격 검증 역할을 구분합니다.'),Q('SSID 숨김만으로 충분한 무선 보안을 제공하나?','아니다. 강한 인증·암호화·관리 설정·업데이트가 필요하다.','이름 숨김과 사용자 인증은 목적이 다릅니다.')],[E('무선 표·인증 그림의 해석 보충','802.11i는 보안 개선 규격이므로 b/a/g/n처럼 전송률 세대로만 배열하면 혼동이 생깁니다. 또한 EAP-TLS는 인증서와 TLS를 사용하는 방식이어서 PPT의 해시 도전·응답 하나로 모든 Enterprise 인증을 설명할 수 없습니다.','추가 계산으로 24비트 IV의 조합 수는 2의 24승, 16,777,216가지입니다. 이는 가능한 IV 수이며 그 수만큼 반드시 수집해야만 공격이 가능하다거나 동일한 시간이 걸린다는 뜻은 아닙니다.')])
 ]
